// Crear relaciones usuario-proyecto
const relations = [];
for (const item of items) {
  const userId = item.json.userId;
  const projects = item.json.projects || [];

  for (const project of projects) {
    relations.push({
      json: {
        user_gitlab_id: userId,
        project_gitlab_id: project.id,
        access_level: project.access_level,
        project_name: project.name
      }
    });
  }
}
return relations;

