parameters.functionCode:
// Procesar commits y extraer métricas
const processedCommits = [];

for (const item of items) {
  const commits = item.json.commits || [];
  const projectId = item.json.projectId;

  for (const commit of commits) {
    const commitDate = new Date(commit.created_at);

    processedCommits.push({
      json: {
        gitlab_id: commit.id,
        project_gitlab_id: projectId,
        title: commit.title,
        message: commit.message,
        author_name: commit.author_name,
        author_email: commit.author_email,
        created_at_gitlab: commit.created_at,
        committed_date: commit.committed_date,
        web_url: commit.web_url,
        stats_additions: commit.stats?.additions || 0,
        stats_deletions: commit.stats?.deletions || 0,
        stats_total: commit.stats?.total || 0,
        date: commitDate.toISOString().split('T')[0],
        hour: commitDate.getHours(),
        weekday: commitDate.getDay()
      }
    });
  }
}

return processedCommits;

