parameters.functionCode:
// Agregar métricas horarias
const hourlyMetrics = {};

for (const item of items) {
  const userEmail = item.json.author_email;
  const date = item.json.date;
  const hour = item.json.hour;
  const key = `${userEmail}-${date}-${hour}`;

  if (!hourlyMetrics[key]) {
    hourlyMetrics[key] = {
      author_email: userEmail,
      date: date,
      hour: hour,
      commit_count: 0,
      additions_total: 0,
      deletions_total: 0,
      files_changed_total: 0
    };
  }

  hourlyMetrics[key].commit_count += 1;
  hourlyMetrics[key].additions_total += item.json.stats_additions || 0;
  hourlyMetrics[key].deletions_total += item.json.stats_deletions || 0;
  hourlyMetrics[key].files_changed_total += 1;
}

return Object.values(hourlyMetrics).map(metric => ({ json: metric }));

