parameters.functionCode:
// Calcular métricas diarias
const dailyMetrics = {};

for (const item of items) {
  const userEmail = item.json.author_email;
  const date = item.json.date;
  const key = `${userEmail}-${date}`;

  if (!dailyMetrics[key]) {
    dailyMetrics[key] = {
      author_email: userEmail,
      date: date,
      commit_count: 0,
      additions_total: 0,
      deletions_total: 0,
      files_changed_total: 0,
      hours: new Set()
    };
  }

  dailyMetrics[key].commit_count += 1;
  dailyMetrics[key].additions_total += item.json.stats_additions || 0;
  dailyMetrics[key].deletions_total += item.json.stats_deletions || 0;
  dailyMetrics[key].files_changed_total += 1;
  dailyMetrics[key].hours.add(item.json.hour);
}

// Calcular métricas agregadas
const result = [];
for (const key in dailyMetrics) {
  const metric = dailyMetrics[key];
  const avgCommitsPerHour = metric.hours.size > 0 ? metric.commit_count / metric.hours.size : 0;

  result.push({
    json: {
      author_email: metric.author_email,
      date: metric.date,
      commit_count: metric.commit_count,
      additions_total: metric.additions_total,
      deletions_total: metric.deletions_total,
      files_changed_total: metric.files_changed_total,
      avg_commits_per_hour: parseFloat(avgCommitsPerHour.toFixed(2))
    }
  });
}

return result;

